"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[57856],{52251(e,a,n){n.r(a),n.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>l});const o=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Una introducci\xf3n a un curso sobre aplicaciones pr\xe1cticas de la computaci\xf3n cu\xe1ntica.","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Una introducci\xf3n a un curso sobre aplicaciones pr\xe1cticas de la computaci\xf3n cu\xe1ntica.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Computaci\xf3n cu\xe1ntica pr\xe1ctica a corto plazo","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Descripci\xf3n general","permalink":"/learning/courses/quantum-business-foundations/"}}');var s=n(74848),i=n(28453);const r={description:"Una introducci\xf3n a un curso sobre aplicaciones pr\xe1cticas de la computaci\xf3n cu\xe1ntica.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},c="Introducci\xf3n a la computaci\xf3n cu\xe1ntica pr\xe1ctica a corto plazo {#introduction-to-practical-near-term-quantum-computing}",t={},l=[{value:"Para qu\xe9 podr\xedan ser \xfatiles los ordenadores cu\xe1nticos",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Utilidad y ventaja cu\xe1nticas a corto plazo",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Una breve introducci\xf3n a la teor\xeda de la complejidad",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"De la teor\xeda de la complejidad a la evidencia pr\xe1ctica",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"\xc1reas de aplicaci\xf3n y casos de estudio del curso",id:"application-areas-and-course-case-studies",level:2},{value:"Simulaci\xf3n hamiltoniana",id:"hamiltonian-simulation",level:3},{value:"Optimizaci\xf3n",id:"optimization",level:3},{value:"Aprendizaje autom\xe1tico cu\xe1ntico",id:"quantum-machine-learning",level:3},{value:"Ecuaciones en derivadas parciales",id:"partial-differential-equations",level:3},{value:"Conclusi\xf3n",id:"conclusion",level:2}];function d(e){const a={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:["\n",(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Introducci\xf3n a la computaci\xf3n cu\xe1ntica pr\xe1ctica a corto plazo"})}),"\n",(0,s.jsx)(a.p,{children:"Desde que se propusieron los primeros ordenadores cu\xe1nticos hace m\xe1s de cuatro d\xe9cadas, la pregunta ha sido: \xbfhasta d\xf3nde podr\xeda extender este nuevo enfoque los l\xedmites de la computaci\xf3n? La inform\xe1tica te\xf3rica nos dio algunas respuestas emocionantes. Los ordenadores cu\xe1nticos podr\xedan factorizar enteros grandes de forma dr\xe1sticamente m\xe1s r\xe1pida que los mejores m\xe9todos cl\xe1sicos conocidos, acelerar la b\xfasqueda no estructurada y simular sistemas cu\xe1nticos de manera m\xe1s natural. Sin embargo, muchas de estas ideas supon\xedan un futuro ordenador cu\xe1ntico tolerante a fallos y de gran escala."}),"\n",(0,s.jsx)(a.p,{children:"La tecnolog\xeda a\xfan no ha alcanzado todos esos objetivos te\xf3ricos, pero mejora r\xe1pidamente. Hoy los investigadores pueden usar procesadores cu\xe1nticos para explorar problemas cient\xedficos e industriales reales. En este curso adquiriremos experiencia pr\xe1ctica con algunas de las aplicaciones m\xe1s prometedoras. Estimaremos propiedades de baja energ\xeda de un modelo molecular complejo, simularemos la din\xe1mica de una teor\xeda gauge en red y exploraremos c\xf3mo se puede trasladar a un ordenador cu\xe1ntico un problema de cartera financiera. Tambi\xe9n veremos \xe1reas m\xe1s recientes en las que apenas hemos empezado a entender lo que los ordenadores cu\xe1nticos podr\xedan ofrecer, como el aprendizaje autom\xe1tico cu\xe1ntico (QML) y los enfoques cu\xe1nticos para las ecuaciones en derivadas parciales (PDE)."}),"\n",(0,s.jsx)(a.p,{children:"Muchos de los ejemplos de este curso son lo bastante peque\xf1os como para que un ordenador cl\xe1sico los resuelva. Eso es intencional. El objetivo es darte una experiencia tangible del proceso completo de usar un ordenador cu\xe1ntico para abordar un problema del mundo real. Algunos ejemplos representan problemas en los que la ventaja cu\xe1ntica podr\xeda surgir a escalas mucho mayores. En otros ejemplos usamos un m\xe9todo simplificado para que los detalles de implementaci\xf3n no oculten la idea cu\xe1ntica central."}),"\n",(0,s.jsx)(a.p,{children:"Al final del curso, deber\xedas tener una visi\xf3n general de las principales aplicaciones cu\xe1nticas y una intuici\xf3n de por qu\xe9 los ordenadores cu\xe1nticos podr\xedan ser \xfatiles en \xe1reas concretas. Conocer\xe1s t\xe9cnicas comunes para representar problemas en ordenadores cu\xe1nticos, aprender\xe1s c\xf3mo colaboran los m\xe9todos cu\xe1nticos y cl\xe1sicos, y empezar\xe1s a reconocer qu\xe9 herramientas y compromisos importan para distintos tipos de problemas."}),"\n",(0,s.jsx)(a.p,{children:"En esta primera lecci\xf3n cubriremos algunos de los conceptos fundamentales y la terminolog\xeda que te ayudan a comprender las aplicaciones de la computaci\xf3n cu\xe1ntica a alto nivel, y te daremos una visi\xf3n general de las principales \xe1reas de aplicaci\xf3n que la comunidad cient\xedfica persigue activamente."}),"\n",(0,s.jsx)(a.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Para qu\xe9 podr\xedan ser \xfatiles los ordenadores cu\xe1nticos"}),"\n",(0,s.jsx)(a.p,{children:"A menudo se presenta a los ordenadores cu\xe1nticos como competidores de los cl\xe1sicos, pero una forma m\xe1s adecuada de pensar en ellos es como recursos especializados dentro de flujos de trabajo cl\xe1sicos m\xe1s amplios. La pregunta importante, entonces, es qu\xe9 partes de un c\xe1lculo se adaptan especialmente bien al hardware cu\xe1ntico. La respuesta m\xe1s intuitiva proviene de los problemas que ya son cu\xe1nticos, como el comportamiento de mol\xe9culas, materiales y campos cu\xe1nticos. Un procesador cu\xe1ntico puede representar y manipular estados cu\xe1nticos directamente, mientras que los recursos necesarios para una descripci\xf3n cl\xe1sica general crecen exponencialmente con el tama\xf1o del sistema."}),"\n",(0,s.jsx)(a.p,{children:"El caso es m\xe1s sutil para los problemas con entradas y salidas cl\xe1sicas, pero aun as\xed hay buenas razones para explorarlos. Los problemas de optimizaci\xf3n est\xe1n muy extendidos y tienen gran importancia econ\xf3mica, de modo que incluso una mejora modesta en la calidad de la soluci\xf3n o en el tiempo de ejecuci\xf3n podr\xeda ser valiosa. Los algoritmos cu\xe1nticos tambi\xe9n podr\xedan ofrecer nuevas formas de explorar espacios de soluciones complicados o de aprovechar la estructura de ciertas clases de problemas. El aprendizaje autom\xe1tico cu\xe1ntico tiene una fuerte motivaci\xf3n te\xf3rica para ciertos problemas con entradas cl\xe1sicas, incluidos la clasificaci\xf3n estructurada y el procesamiento de conjuntos de datos masivos. Sin embargo, sigue siendo una pregunta abierta si estos resultados pueden traducirse en una ventaja pr\xe1ctica sobre datos cl\xe1sicos del mundo real. Las ecuaciones en derivadas parciales describen muchos sistemas importantes de la ciencia, la ingenier\xeda y las finanzas, y los algoritmos cu\xe1nticos podr\xedan mejorar el escalado de ciertas simulaciones de alta dimensi\xf3n y de grandes problemas de \xe1lgebra lineal."}),"\n",(0,s.jsx)(a.p,{children:"Sin embargo, en estas tres \xe1reas el costo de preparar las entradas cl\xe1sicas, ejecutar el c\xe1lculo cu\xe1ntico y extraer una respuesta cl\xe1sica \xfatil puede superar el beneficio del paso cu\xe1ntico. Tendremos presentes estos desaf\xedos pr\xe1cticos mientras exploramos c\xf3mo se aplican los m\xe9todos cu\xe1nticos en cada \xe1rea."}),"\n",(0,s.jsx)(a.h2,{id:"near-term-quantum-utility-and-advantage",children:"Utilidad y ventaja cu\xe1nticas a corto plazo"}),"\n",(0,s.jsx)(a.p,{children:"Este curso no trata espec\xedficamente de la ventaja cu\xe1ntica, pero es inevitable hablar de ella. La motivaci\xf3n fundamental de las aplicaciones cu\xe1nticas es usar recursos cu\xe1nticos para ampliar lo que los ordenadores cl\xe1sicos pueden hacer por s\xed solos: producir resultados m\xe1s precisos, llegar a soluciones m\xe1s r\xe1pido o resolver problemas que de otro modo son inaccesibles. Los siguientes t\xe9rminos relacionados nos ayudan a hablar con claridad del progreso que observamos:"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Aceleraci\xf3n cu\xe1ntica (quantum speedup):"})," a medida que aumenta el tama\xf1o del problema, el tiempo que requiere un m\xe9todo cu\xe1ntico escala de forma m\xe1s favorable que el del mejor m\xe9todo cl\xe1sico relevante para la misma tarea."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Ventaja cu\xe1ntica:"})," un c\xe1lculo habilitado por la computaci\xf3n cu\xe1ntica supera a los mejores enfoques cl\xe1sicos relevantes en una tarea bien definida y con una m\xe9trica significativa. M\xe1s que un hito \xfanico y permanente, la ventaja cu\xe1ntica es una frontera en evoluci\xf3n que se desplaza a medida que mejoran tanto los m\xe9todos cu\xe1nticos como los cl\xe1sicos."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Utilidad cu\xe1ntica:"})," un c\xe1lculo cu\xe1ntico contribuye a un resultado cient\xedfico o t\xe9cnico \xfatil. Opera a una escala, profundidad y precisi\xf3n que van m\xe1s all\xe1 de la simulaci\xf3n cl\xe1sica pr\xe1ctica por fuerza bruta, sin que necesariamente supere al mejor m\xe9todo cl\xe1sico."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Algoritmo a corto plazo:"})," un algoritmo dise\xf1ado para los procesadores cu\xe1nticos actuales, que usa profundidades de circuito limitadas y suele depender del posprocesamiento cl\xe1sico y de la mitigaci\xf3n de errores en lugar de la correcci\xf3n de errores cu\xe1nticos completa."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Computaci\xf3n cu\xe1ntica tolerante a fallos:"})," en el futuro, la computaci\xf3n cu\xe1ntica usar\xe1 la correcci\xf3n de errores cu\xe1nticos para proteger los qubits l\xf3gicos durante todo un c\xe1lculo. Cuando las tasas de error f\xedsico est\xe1n por debajo del umbral de tolerancia a fallos, los recursos adicionales de correcci\xf3n de errores pueden suprimir los errores l\xf3gicos hasta el nivel que requieren los c\xe1lculos largos y fiables. La tolerancia a fallos hace posibles algoritmos mucho m\xe1s profundos, incluidas implementaciones a gran escala del algoritmo de Shor."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Tolerancia a fallos temprana:"})," la tolerancia a fallos significa que los errores se suprimen, no que se eliminen por completo. En los primeros sistemas tolerantes a fallos todav\xeda hay que tener en cuenta los errores l\xf3gicos residuales, y la profundidad de los circuitos fiables sigue siendo limitada."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Algoritmo heur\xedstico:"})," un m\xe9todo dise\xf1ado para encontrar una buena soluci\xf3n en la pr\xe1ctica sin garantizar la respuesta \xf3ptima ni un tiempo de ejecuci\xf3n determinado."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(a.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Una breve introducci\xf3n a la teor\xeda de la complejidad"}),"\n",(0,s.jsx)(a.p,{children:"En algunas \xe1reas de aplicaci\xf3n tenemos una s\xf3lida raz\xf3n te\xf3rica para esperar que un ordenador cu\xe1ntico pueda tener una ventaja. Para entender de d\xf3nde viene esa confianza, necesitamos un poco de vocabulario de la teor\xeda de la complejidad."}),"\n",(0,s.jsx)(a.p,{children:"La teor\xeda de la complejidad estudia c\xf3mo crecen los recursos necesarios para resolver un problema a medida que este se hace m\xe1s grande. Nos da un mapa \xfatil de d\xf3nde podr\xeda ser posible una aceleraci\xf3n cu\xe1ntica. Unos pocos t\xe9rminos son especialmente importantes para este curso:"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"P:"})," problemas que un ordenador cl\xe1sico puede resolver de forma eficiente, es decir, cuyos recursos necesarios crecen de forma polin\xf3mica con el tama\xf1o del problema."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"NP:"})," problemas para los que se puede comprobar eficientemente una soluci\xf3n propuesta, aunque encontrar esa soluci\xf3n pueda ser muy dif\xedcil."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"NP-hard:"})," problemas que son al menos tan dif\xedciles como todos los problemas de NP. Un problema NP-hard no necesariamente pertenece a NP. Muchos problemas de optimizaci\xf3n son NP-hard."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"NP-complete:"})," problemas que son a la vez NP-hard y pertenecen a NP. Son los problemas de decisi\xf3n m\xe1s dif\xedciles dentro de NP."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"BQP:"})," problemas que un ordenador cu\xe1ntico puede resolver eficientemente con una probabilidad de error acotada."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:"Se conocen algunas relaciones entre estas categor\xedas. P est\xe1 contenido tanto en NP como en BQP, porque un problema que puede resolverse eficientemente en un ordenador cl\xe1sico tambi\xe9n puede comprobarse de forma cl\xe1sica y resolverse en un ordenador cu\xe1ntico. Otras relaciones siguen abiertas. No sabemos si P es igual a NP ni si NP est\xe1 contenido en BQP. Sin embargo, los investigadores generalmente creen que P es m\xe1s peque\xf1o que NP y que BQP, y que los ordenadores cu\xe1nticos no pueden resolver eficientemente todos los problemas NP-complete. En pocas palabras, un ordenador cu\xe1ntico no es una caja m\xe1gica que resuelve al instante todos los problemas dif\xedciles."}),"\n",(0,s.jsx)(a.p,{children:"Los argumentos m\xe1s s\xf3lidos basados en la complejidad a favor de la computaci\xf3n cu\xe1ntica se aplican a ciertos tipos de problemas. El algoritmo de Shor escala de forma dr\xe1sticamente mejor que los mejores algoritmos cl\xe1sicos conocidos para la factorizaci\xf3n y los logaritmos discretos, aunque no se ha demostrado que la factorizaci\xf3n quede fuera de P. La simulaci\xf3n cu\xe1ntica general tambi\xe9n tiene una base te\xf3rica s\xf3lida. Algunos problemas de simulaci\xf3n cu\xe1ntica son BQP-complete, lo que significa que resolverlos eficientemente de forma cl\xe1sica equivaldr\xeda a simular eficientemente cualquier c\xe1lculo cu\xe1ntico. Una simulaci\xf3n cl\xe1sica eficiente de ese tipo es muy poco plausible, y esa es una de las razones por las que la simulaci\xf3n hamiltoniana cu\xe1ntica se considera un \xe1rea de aplicaci\xf3n tan prometedora."}),"\n",(0,s.jsx)(a.p,{children:"Algunas PDE de alta dimensi\xf3n pueden reducirse a problemas de sistemas lineales BQP-complete, lo que nos da una s\xf3lida raz\xf3n para esperar una aceleraci\xf3n cu\xe1ntica cuando las entradas y salidas pueden manejarse de forma eficiente. El QML tiene ejemplos similares: algunas tareas con datos cu\xe1nticos son BQP-complete, y algunos modelos cu\xe1nticos pueden generar muestras que son dif\xedciles de reproducir de forma cl\xe1sica."}),"\n",(0,s.jsx)(a.p,{children:"El caso es menos directo para la optimizaci\xf3n. No se espera que los ordenadores cu\xe1nticos resuelvan eficientemente problemas NP-hard arbitrarios, pero aun as\xed podr\xedan ayudar con problemas estructurados, instancias particulares o pasos espec\xedficos de un flujo de trabajo de optimizaci\xf3n. El algoritmo de Grover, por ejemplo, ofrece una aceleraci\xf3n cuadr\xe1tica para la b\xfasqueda no estructurada. Es una mejora significativa, aunque la ra\xedz cuadrada de un espacio de b\xfasqueda astron\xf3micamente grande siga siendo astron\xf3mica."}),"\n",(0,s.jsx)(a.h2,{id:"from-complexity-theory-to-practical-evidence",children:"De la teor\xeda de la complejidad a la evidencia pr\xe1ctica"}),"\n",(0,s.jsx)(a.p,{children:"La teor\xeda de la complejidad puede decirnos d\xf3nde podr\xeda ser posible una aceleraci\xf3n cu\xe1ntica, pero normalmente no puede decirnos c\xf3mo se comporta un m\xe9todo en un problema concreto o en un ordenador cu\xe1ntico concreto. Muchos de los m\xe9todos que se usan en el hardware actual son heur\xedsticos. Est\xe1n dise\xf1ados para encontrar buenas respuestas en la pr\xe1ctica, pero no garantizan la mejor respuesta posible ni un tiempo de ejecuci\xf3n determinado."}),"\n",(0,s.jsx)(a.p,{children:"Las heur\xedsticas no son exclusivas de la computaci\xf3n cu\xe1ntica, y llamar heur\xedstico a un m\xe9todo no significa que sea poco fiable o poco cient\xedfico. La optimizaci\xf3n cl\xe1sica, el aprendizaje autom\xe1tico y la qu\xedmica computacional dependen en gran medida de heur\xedsticas cuando una soluci\xf3n exacta ser\xeda demasiado costosa. Una heur\xedstica cu\xe1ntica podr\xeda ofrecer una nueva forma de explorar un espacio de soluciones, preparar estados \xfatiles o identificar candidatos prometedores. Que funcione bien es una cuesti\xf3n emp\xedrica: tenemos que ejecutarla y medir el resultado."}),"\n",(0,s.jsx)(a.p,{children:"Como las heur\xedsticas no vienen con garant\xedas de rendimiento, las evaluamos con una m\xe9trica de \xe9xito clara, l\xedneas base cl\xe1sicas s\xf3lidas y pruebas con distintos tama\xf1os de problema. Esto nos ayuda a ver d\xf3nde funciona bien un m\xe9todo y c\xf3mo cambia su rendimiento a medida que el problema escala."}),"\n",(0,s.jsx)(a.h2,{id:"application-areas-and-course-case-studies",children:"\xc1reas de aplicaci\xf3n y casos de estudio del curso"}),"\n",(0,s.jsx)(a.p,{children:"Organizamos el curso en torno a cuatro grandes \xe1reas de aplicaci\xf3n. No cubren todos los usos posibles de un ordenador cu\xe1ntico, pero nos dan una forma \xfatil de comparar d\xf3nde est\xe1n los argumentos m\xe1s s\xf3lidos y d\xf3nde est\xe1n las preguntas abiertas."}),"\n",(0,s.jsx)(a.h3,{id:"hamiltonian-simulation",children:"Simulaci\xf3n hamiltoniana"}),"\n",(0,s.jsx)(a.p,{children:"La simulaci\xf3n hamiltoniana incluye la estimaci\xf3n de energ\xedas, el estudio de propiedades qu\xedmicas y de materiales, y el modelado de c\xf3mo cambian los sistemas cu\xe1nticos con el tiempo. Abarca la qu\xedmica, la ciencia de materiales, la f\xedsica de la materia condensada y la f\xedsica de altas energ\xedas y nuclear. Nuestros casos de estudio examinan un modelo de hierro-azufre fuertemente correlacionado mediante diagonalizaci\xf3n cu\xe1ntica basada en muestras y simulan la din\xe1mica de hadrones usando una representaci\xf3n en red que respeta las simetr\xedas. Son dos ejemplos de un campo mucho m\xe1s amplio, que tambi\xe9n incluye mecanismos de reacci\xf3n, materiales magn\xe9ticos y otras din\xe1micas de muchos cuerpos."}),"\n",(0,s.jsx)(a.h3,{id:"optimization",children:"Optimizaci\xf3n"}),"\n",(0,s.jsx)(a.p,{children:"La optimizaci\xf3n aparece en todas partes, desde las finanzas y la log\xedstica hasta la planificaci\xf3n de horarios y los sistemas de energ\xeda. Tambi\xe9n es un \xe1rea en la que resulta dif\xedcil establecer una ventaja, porque los solucionadores cl\xe1sicos son extremadamente capaces y las traducciones al \xe1mbito cu\xe1ntico pueden a\xf1adir una sobrecarga costosa. Nuestro caso de estudio usa la selecci\xf3n de carteras para explorar c\xf3mo se representa, se ejecuta y se eval\xfaa un problema de optimizaci\xf3n, sin suponer que un ordenador cu\xe1ntico encuentra autom\xe1ticamente el \xf3ptimo exacto."}),"\n",(0,s.jsx)(a.h3,{id:"quantum-machine-learning",children:"Aprendizaje autom\xe1tico cu\xe1ntico"}),"\n",(0,s.jsx)(a.p,{children:"El aprendizaje autom\xe1tico cu\xe1ntico se pregunta si los circuitos cu\xe1nticos o los datos cu\xe1nticos pueden mejorar una tarea de aprendizaje. Entre las cuestiones importantes est\xe1n la codificaci\xf3n de datos, el costo del entrenamiento, la generalizaci\xf3n y la comparaci\xf3n con modelos cl\xe1sicos s\xf3lidos."}),"\n",(0,s.jsx)(a.h3,{id:"partial-differential-equations",children:"Ecuaciones en derivadas parciales"}),"\n",(0,s.jsx)(a.p,{children:"Las ecuaciones en derivadas parciales describen sistemas como fluidos, calor y ondas. Los algoritmos cu\xe1nticos podr\xedan acelerar partes de algunos flujos de trabajo de PDE, pero la preparaci\xf3n de datos y la extracci\xf3n de una respuesta cl\xe1sica \xfatil pueden suponer costos importantes. El caso de estudio espec\xedfico todav\xeda se est\xe1 desarrollando."}),"\n",(0,s.jsx)(a.p,{children:"En las lecciones siguientes haremos las mismas preguntas b\xe1sicas en cada \xe1rea: \xbfcu\xe1l es el problema, por qu\xe9 podr\xeda ayudar la computaci\xf3n cu\xe1ntica, cu\xe1les son las limitaciones y qu\xe9 muestra realmente la evidencia? Empezaremos con la simulaci\xf3n hamiltoniana, donde el problema mismo es cu\xe1ntico."}),"\n",(0,s.jsx)(a.h2,{id:"conclusion",children:"Conclusi\xf3n"}),"\n",(0,s.jsx)(a.p,{children:"Hemos cubierto mucho terreno, pero la idea principal es simple: los ordenadores cu\xe1nticos son herramientas especializadas, y su valor depende de usar el m\xe9todo cu\xe1ntico adecuado para el problema adecuado o para una parte de un problema mayor. La simulaci\xf3n hamiltoniana tiene la base te\xf3rica m\xe1s clara, la optimizaci\xf3n cuenta con un conjunto maduro de m\xe9todos heur\xedsticos y de benchmarks, y el QML y las PDE ofrecen direcciones prometedoras que todav\xeda est\xe1n en desarrollo."}),"\n",(0,s.jsx)(a.p,{children:"En las lecciones siguientes pasaremos de esta visi\xf3n general a ejemplos pr\xe1cticos. Para cada aplicaci\xf3n nos preguntaremos qu\xe9 problema intentamos resolver, qu\xe9 papel desempe\xf1a el ordenador cu\xe1ntico, c\xf3mo se interpreta el resultado y qu\xe9 podemos aprender de \xe9l. El objetivo es construir tu intuici\xf3n sobre d\xf3nde podr\xeda ayudar la computaci\xf3n cu\xe1ntica y qu\xe9 hace falta para convertir una idea prometedora en un c\xe1lculo real."}),"\n"]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,a,n){n.d(a,{R:()=>r,x:()=>c});var o=n(96540);const s={},i=o.createContext(s);function r(e){const a=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(i.Provider,{value:a},e.children)}}}]);